probe_sources.sparse_probe.cu:
#include "cuda/glm_vq_attention.cuh"
#include <vector>
#include <cstring>

enum { HEADS = 64, DIM = 256, LATENT = 512, STRIDE = 2051 };
struct sparse_test {
    std::vector<void *> allocations;
    cublasHandle_t handle = nullptr;
    ~sparse_test() {
        if (handle) { cublasDestroy(handle); }
        for (void *p : allocations) { cudaFree(p); }
    }
    bool alloc(void **p, uint64_t bytes, const void *host = nullptr) {
        if (cudaMalloc(p, bytes) != cudaSuccess) { return false; }
        allocations.push_back(*p);
        return !host || cudaMemcpy(*p, host, bytes, cudaMemcpyHostToDevice) == cudaSuccess;
    }
};
extern "C" int test_sparse(const uint16_t *weight, const uint16_t *cache,
        const float *query, const int32_t *selection, const uint32_t *position,
        float *out, uint16_t *q_stage, uint16_t *p_stage, uint16_t *l_stage,
        uint32_t keys, uint32_t rows, uint32_t factored) {
    if (!keys || keys > 8192 || !rows || rows > 2 || (factored && rows != 1)) { return -1; }
    sparse_test c;
    __nv_bfloat16 *w = nullptr, *x = nullptr, *expanded = nullptr;
    float *q = nullptr, *y = nullptr;
    uint32_t *pos = nullptr;
    int32_t *selected = nullptr;
    void *scratch = nullptr, *workspace = nullptr;
    const uint64_t wn = HEADS * 2ull * DIM * LATENT, xn = (uint64_t)keys * LATENT;
    const uint64_t qn = (uint64_t)rows * HEADS * DIM, low = HEADS * LATENT;
    const auto layout = glmvq_attn_bytes(rows, keys, HEADS, DIM);
    if (!c.alloc((void **)&w, wn * 2, weight) || !c.alloc((void **)&x, xn * 2, cache) ||
        !c.alloc((void **)&q, qn * sizeof(float), query) || !c.alloc((void **)&y, qn * sizeof(float)) ||
        !c.alloc((void **)&pos, rows * sizeof(uint32_t), position) ||
        !c.alloc((void **)&selected, (uint64_t)rows * STRIDE * sizeof(int32_t), selection) ||
        !c.alloc((void **)&expanded, (uint64_t)keys * HEADS * 2 * DIM * 2) ||
        !c.alloc(&scratch, layout.bytes) || !c.alloc(&workspace, 32ull << 20) ||
        cublasCreate(&c.handle) != CUBLAS_STATUS_SUCCESS ||
        cublasSetWorkspace(c.handle, workspace, 32ull << 20) != CUBLAS_STATUS_SUCCESS) { return -2; }
    cublasStatus_t status;
    if (factored) {
        status = glmvq_latent_attn(c.handle, w, x, q, y, pos, rows, keys, HEADS, DIM,
            LATENT, scratch, layout.bytes, nullptr, selected, STRIDE);
    } else {
        const float alpha = 1.0f, beta = 0.0f;
        status = cublasGemmEx(c.handle, CUBLAS_OP_T, CUBLAS_OP_N,
            HEADS * 2 * DIM, keys, LATENT, &alpha, w, CUDA_R_16BF, LATENT,
            x, CUDA_R_16BF, LATENT, &beta, expanded, CUDA_R_16BF, HEADS * 2 * DIM,
            CUBLAS_COMPUTE_32F, CUBLAS_GEMM_DEFAULT_TENSOR_OP);
        if (status == CUBLAS_STATUS_SUCCESS) {
            status = glmvq_attention(c.handle, q, expanded, y, pos, selected, STRIDE,
                rows, keys, HEADS, DIM, scratch, layout.bytes, nullptr);
        }
    }
    if (status != CUBLAS_STATUS_SUCCESS ||
        cudaMemcpy(out, y, qn * sizeof(float), cudaMemcpyDeviceToHost) != cudaSuccess) { return -3; }
    const uint8_t *base = (const uint8_t *)scratch;
    if (cudaMemcpy(p_stage, base + layout.scores, (uint64_t)rows * keys * HEADS * 2,
            cudaMemcpyDeviceToHost) != cudaSuccess) { return -4; }
    if (factored && (cudaMemcpy(q_stage, base + layout.kv, low * 2, cudaMemcpyDeviceToHost) != cudaSuccess ||
        cudaMemcpy(l_stage, base + layout.kv + low * 2, low * 2, cudaMemcpyDeviceToHost) != cudaSuccess)) { return -5; }
    std::vector<uint16_t> restored(xn);
    std::vector<uint32_t> actual_pos(rows);
    std::vector<int32_t> actual_selected((uint64_t)rows * STRIDE);
    if (cudaMemcpy(restored.data(), x, xn * 2, cudaMemcpyDeviceToHost) != cudaSuccess ||
        memcmp(restored.data(), cache, xn * 2) ||
        cudaMemcpy(actual_pos.data(), pos, rows * 4, cudaMemcpyDeviceToHost) != cudaSuccess ||
        memcmp(actual_pos.data(), position, rows * 4) ||
        cudaMemcpy(actual_selected.data(), selected, (uint64_t)rows * STRIDE * 4, cudaMemcpyDeviceToHost) != cudaSuccess ||
        memcmp(actual_selected.data(), selection, (uint64_t)rows * STRIDE * 4)) { return -6; }
    return 0;
}
